import{_ as n,l as t,o as i,c as d,v as e,p as s,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"Edmonds–Karp 与 Dinic","description":"","frontmatter":{"title":"Edmonds–Karp 与 Dinic","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dinic.md","filePath":"cs/dinic.md","lastUpdated":1789023840000}'),E={name:"cs/dinic.md"};function m(h,a,_,f,D,u){const r=t("Mermaid");return i(),d("div",null,[a[1]||(a[1]=e('<h1 id="edmonds–karp-与-dinic" tabindex="-1">Edmonds–Karp 与 Dinic <a class="header-anchor" href="#edmonds–karp-与-dinic" aria-label="Permalink to &quot;Edmonds–Karp 与 Dinic&quot;">​</a></h1><div class="epigraph"><p>最短增广把 Ford–Fulkerson 变成 $O(VE^2)$；分层网络上的阻塞流把迭代降到 $O(V^2 E)$。</p><footer>—— 据 Edmonds and Karp, Theoretical Improvements in Algorithmic Efficiency for Network Flow Problems, 1972；Dinic, Algorithm for Solution of a Problem of Maximum Flow, 1970；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/max-flow-ff">最大流 Ford–Fulkerson</a>给出残量增广与最大流最小割，并警告：任意增广路可使次数随容量指数。本课不重证割。缺口是<strong>选哪条路</strong>：Edmonds–Karp 每次 BFS 最短（边数最少）增广；Dinic 一次建分层，再推阻塞流。整数容量下二者都多项式。后课二分图匹配把单位容量网络当特例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ford–Fulkerson 是框架。容量很大且每次 \\(\\Delta=1\\) 时，增广次数可达 \\(\\Theta(|f^*|)\\)。Edmonds–Karp：残量上 BFS 找 \\(s\\)–\\(t\\) 最短路再增。关键事实：最短路长度不减，每条边作为临界边的次数 \\(O(V)\\)，故增广 \\(O(VE)\\) 次，每次 \\(O(E)\\)，总 \\(O(VE^2)\\)。缺口是这份选路规则，不是新的流定义。</p><p>Dinic：按残量 BFS 分层，\\(d(v)\\) 为边数距离。只沿层间边 \\(d(w)=d(v)+1\\) 推流，直到 \\(s\\) 到 \\(t\\) 不再连通（阻塞流）。然后重建分层。层数增加，至多 \\(V-1\\) 相。单位容量或简单图上实现可到 \\(O(V^2 E)\\) 量级（经典界）；更紧的实现不在本课展开。</p><h3 id="阻塞流不是一次增广" tabindex="-1">阻塞流不是一次增广 <a class="header-anchor" href="#阻塞流不是一次增广" aria-label="Permalink to &quot;阻塞流不是一次增广&quot;">​</a></h3><p>一次阻塞流可以同时填满分层里的许多条路，相当于一批最短增广。Dinic 1970 的「功率」估计即分层推进。不要把 Dinic 写成「再跑一遍 Edmonds–Karp」。</p><p><span class="marginnote">Edmonds–Karp 1972 证明最短增广多项式。Dinic（Dinitz）1970 更早给出分层。CLRS 以 Edmonds–Karp 为定理级实现，Dinic 作进阶。本课两条都要：一条证明墙是多项式，一条给更常用的推进。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>EK：循环 BFS，沿树增广，更新残量，直至 \\(t\\) 不可达。Dinic：循环 { BFS 分层；若 \\(t\\) 不在分层则停；DFS/指针沿层推阻塞流 }。</p>',11)),(i(),s(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF%5B%22%E6%AE%8B%E9%87%8F%E5%8F%AF%E5%A2%9E%E5%B9%BF%22%5D%20--%3E%20EK%5B%22BFS%20%E6%9C%80%E7%9F%AD%E5%A2%9E%E5%B9%BF%20O(VE%5E2)%22%5D%0A%20%20FF%20--%3E%20DIN%5B%22%E5%88%86%E5%B1%82%20%2B%20%E9%98%BB%E5%A1%9E%E6%B5%81%22%5D%0A%20%20DIN%20--%3E%20POLY%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E7%9B%B8%E6%95%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>容量有理先化为整数。无理容量仍可能病态，主干用整数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最短增广使「距离标号」单调，分析才能数临界边。Dinic 的当前弧优化避免反复扫邻接表，是实现零件，不改变分层正确性。单位容量网络（匹配）上界更好，下一课用，本课不把匹配写完。</p><p>不要在有负容量的「流」上套本课；模型仍是上一课的容量约束与守恒。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写推送重标、不写费用流。最小割在增广结束时仍是 \\(s\\) 侧可达集。后课默认：要多项式最坏，最短增广或 Dinic；二分图匹配化成单位容量最大流。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Edmonds–Karp：最短增广，\\(O(VE^2)\\)。</li><li>Dinic：分层阻塞流，相数 \\(O(V)\\)。</li><li>仍是残量增广；选路决定次数。</li><li>出处：Dinic, 1970；Edmonds and Karp, 1972；CLRS 第 26 章。</li></ul>',8))])}const A=n(E,[["render",m]]);export{F as __pageData,A as default};
